// Capture agent service — WebSocket server on 127.0.0.1:8766.
//
// The side panel connects here while a capture is pending, sends an `ask`
// (capture tree + question), streams the agent's reasoning back, and on settle
// receives { sessionId, sessionFile, model, cost } so it can stash an `agent`
// envelope on the pending capture before Save.
//
// Protocol (JSON messages):
//   panel → service: { type:"ask", captureId, tree, messages?, prompt }
//                    { type:"follow_up", captureId, prompt }
//                    { type:"abort", captureId }
//   service → panel: { type:"ready" }
//                    { type:"delta", captureId, text }
//                    { type:"tool", captureId, tool, arg }
//                    { type:"settled", captureId, sessionId, sessionFile, model, cost }
//                    { type:"error", captureId, message }
//
// Env:
//   AGENT_PORT        WebSocket port (default 8766)
//   AGENT_DATA_DIR    evidence root (default ../server/data under this repo)
//   AGENT_MOCK=1      stub mode: returns synthetic deltas + a settled event
//                     without hitting OpenRouter (used for tests/smoke).
//   OPENROUTER_API_KEY  required in real mode; never ships in the browser.

import http from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { WebSocketServer, WebSocket } from "ws";

import { CaptureAgent } from "./agent.js";
import { makeSystemPrompt } from "./agent.js";
import { costOfMessages, currentModelOf, newSessionId, persistSession } from "./persist.js";

const ROOT = path.dirname(fileURLToPath(import.meta.url));
export const DEFAULT_DATA_DIR = path.resolve(ROOT, "..", "server", "data");
export const DEFAULT_PORT = 8766;

function dataDir() {
  return process.env.AGENT_DATA_DIR ? path.resolve(process.env.AGENT_DATA_DIR) : DEFAULT_DATA_DIR;
}

const IS_MOCK = process.env.AGENT_MOCK === "1";

// ---- messaging helpers ------------------------------------------------------

function send(socket, obj) {
  if (socket && socket.readyState === WebSocket.OPEN) {
    socket.send(JSON.stringify(obj));
  }
}

// A short (safe) transcript of prior turns, used to carry context when a fresh
// session is created (e.g. after a panel reconnect) via the `messages` field.
function serializeMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0) return "";
  const take = messages.slice(-40);
  const parts = [];
  for (const m of take) {
    const role = (m && m.role) || "";
    let content = m && m.content;
    if (Array.isArray(content)) {
      content = content
        .filter((c) => c && c.type === "text")
        .map((c) => c.text)
        .join(" ");
    }
    if (typeof content === "string" && content.trim()) {
      parts.push(`${role === "assistant" ? "Assistant" : role === "user" ? "User" : role}: ${content.trim()}`);
    }
  }
  return parts.length ? `\n\nPrior conversation so far:\n${parts.join("\n")}` : "";
}

// ---- mock inference (AGENT_MOCK=1) -----------------------------------------

// A tiny "assistant" that streams a deterministic answer and settles, so the
// service + panel protocol is verifiable without an OpenRouter key.
function buildMockAnswer(prompt, tree) {
  const links = [];
  const walk = (n) => {
    for (const l of n.links || []) links.push(l);
    for (const c of n.children || []) walk(c);
  };
  walk(tree || {});
  const urlLine = links.length > 0 ? `\n\nRelevant urls in the capture: ${links[0]}` : "";
  const lines = [
    "This is a stubbed agent answer (AGENT_MOCK=1; no OpenRouter call was made).\n",
    `Your question: "${prompt}".`,
    `The capture contains ${(tree && tree.tweet_text) ? "tweet text" : "a tweet"}${links.length ? ` and ${links.length} link(s)` : ""}.`,
    urlLine,
    "\nA real run would reason over the capture and its urls with the fetch_url tool.",
  ];
  return lines.join("\n");
}

class MockHandle {
  constructor({ captureId, socket, dataDir, model }) {
    this.captureId = captureId;
    this.socket = socket;
    this.dataDir = dataDir;
    this.model = model;
    this.turns = [];
    this.sessionId = newSessionId();
    this.timers = [];
  }
  run(msg) {
    const { prompt, tree } = msg;
    const answer = buildMockAnswer(prompt, tree);
    this.turns.push({ role: "user", content: prompt });
    const chunks = answer.match(/.{1,40}/gs) || [];
    chunks.forEach((chunk, i) => {
      this.timers.push(
        setTimeout(() => {
          send(this.socket, { type: "delta", captureId: this.captureId, text: chunk });
        }, 30 * (i + 1))
      );
    });
    const settledAt = 60 + 30 * chunks.length;
    this.timers.push(
      setTimeout(() => {
        this.turns.push({ role: "assistant", content: answer });
        const { sessionId, sessionFile } = persistSession(
          this.dataDir,
          this.sessionId,
          this.turns.slice()
        );
        send(this.socket, {
          type: "settled",
          captureId: this.captureId,
          sessionId,
          sessionFile,
          model: this.model,
          cost: 0,
        });
      }, settledAt)
    );
  }
  abort() {
    for (const t of this.timers) clearTimeout(t);
    this.timers = [];
  }
}

// ---- main service ----------------------------------------------------------

class AgentService {
  constructor(options = {}) {
    this.dataDir = options.dataDir || dataDir();
    this.cwd = options.cwd || process.cwd();
    this.handles = new Map(); // captureId -> { agent|mock, socket }
  }

  handleFor(captureId) {
    return this.handles.get(captureId);
  }

  async ask(socket, msg) {
    const { captureId, tree, messages, prompt } = msg;
    let handle = this.handles.get(captureId);

    if (handle && handle.agent && handle.agent.isStreaming) {
      send(socket, { type: "error", captureId, message: "Agent is still answering the previous question. Wait for it to finish." });
      return;
    }

    if (!handle || handle.socket !== socket || (handle.mock === false && !handle.agent)) {
      // Fresh handler for this capture (or a reconnect on a new socket).
      if (handle) this.dispose(false);
      handle = this.createHandle(socket, captureId);
    }

    const question = prompt && prompt.trim() ? prompt.trim() : "Analyse this capture.";
    const prior = serializeMessages(messages || []);

    if (handle.mock) {
      handle.mock.run({ prompt: question, tree: tree || {} });
      return;
    }

    try {
      const agent = handle.agent;
      if (!agent.session) await agent.start();
      handle.socket = socket;
      agent.setHandlers({
        onDelta: (text) => send(socket, { type: "delta", captureId, text }),
        onTool: ({ tool, arg }) => send(socket, { type: "tool", captureId, tool, arg }),
        onSettled: (messagesList) => {
          const { sessionId, sessionFile } = persistSession(this.dataDir, handle.sessionId, messagesList);
          const model = String(agent.model && agent.model.id || (currentModelOf(messagesList) || "unknown"));
          const cost = costOfMessages(messagesList);
          send(socket, {
            type: "settled",
            captureId,
            sessionId,
            sessionFile,
            model,
            cost,
          });
        },
      });
      await agent.ask(tree || {}, question + prior);
    } catch (e) {
      send(socket, { type: "error", captureId, message: `Agent unavailable: ${e && e.message ? e.message : e}` });
      this.dispose(captureId);
    }
  }

  async followUp(socket, msg) {
    const { captureId, prompt } = msg;
    const handle = this.handles.get(captureId);
    if (!handle) {
      send(socket, { type: "error", captureId, message: "No active conversation for this capture. Start with an ask." });
      return;
    }
    if (handle.mock) {
      handle.mock.run({ prompt: prompt || "Continue.", tree: {} });
      return;
    }
    const agent = handle.agent;
    if (agent.isStreaming) {
      send(socket, { type: "error", captureId, message: "Agent is still answering. Wait for it to finish." });
      return;
    }
    try {
      await agent.followUp(prompt || "Continue.");
    } catch (e) {
      send(socket, { type: "error", captureId, message: `Agent unavailable: ${e && e.message ? e.message : e}` });
    }
  }

  async abort(msg) {
    const { captureId } = msg;
    const handle = this.handles.get(captureId);
    if (!handle) return;
    if (handle.mock) {
      handle.mock.abort();
      return;
    }
    try {
      if (handle.agent) await handle.agent.abort();
    } catch {
      /* best-effort */
    }
  }

  createHandle(socket, captureId) {
    const handle = { captureId, socket };
    if (process.env.AGENT_MOCK === "1") {
      handle.mock = new MockHandle({
        captureId,
        socket,
        dataDir: this.dataDir,
        model: process.env.AGENT_MODEL || "deepseek/deepseek-v4-flash",
      });
      handle.sessionId = handle.mock.sessionId;
      this.handles.set(captureId, handle);
      return handle;
    }
    handle.agent = new CaptureAgent({ cwd: this.cwd });
    handle.sessionId = newSessionId();
    this.handles.set(captureId, handle);
    return handle;
  }

  dispose(captureId) {
    const handle = this.handles.get(captureId);
    if (!handle) return;
    if (handle.agent) handle.agent.dispose();
    if (handle.mock) handle.mock.abort();
    this.handles.delete(captureId);
  }

  disposeForSocket(socket) {
    for (const [id, handle] of this.handles) {
      if (handle.socket === socket) {
        const hadAgent = !!handle.agent;
        if (hadAgent) handle.agent.dispose();
        if (handle.mock) handle.mock.abort();
        this.handles.delete(id);
      }
    }
  }
}

function onMessage(service, ws, raw) {
  let msg;
  try {
    msg = JSON.parse(raw.toString());
  } catch {
    send(ws, { type: "error", captureId: null, message: "Invalid JSON message" });
    return;
  }
  if (!msg || typeof msg.type !== "string") {
    send(ws, { type: "error", captureId: null, message: "Message must have a type" });
    return;
  }
  const { type, captureId } = msg;
  switch (type) {
    case "ask":
      service.ask(ws, msg).catch((e) =>
        send(ws, { type: "error", captureId, message: `ask failed: ${e && e.message ? e.message : e}` })
      );
      break;
    case "follow_up":
      service.followUp(ws, msg).catch((e) =>
        send(ws, { type: "error", captureId, message: `follow_up failed: ${e && e.message ? e.message : e}` })
      );
      break;
    case "abort":
      service.abort(msg).catch(() => {});
      break;
    default:
      send(ws, { type: "error", captureId, message: `Unknown message type: ${type}` });
  }
}

export function startServer(options = {}) {
  const port = options.port || Number(process.env.AGENT_PORT) || DEFAULT_PORT;
  const service = new AgentService(options);

  const httpServer = http.createServer((_req, res) => {
    res.writeHead(200, { "Content-Type": "text/plain" });
    res.end("capture agent service");
  });

  const wss = new WebSocketServer({ server: httpServer, path: options.path || "/" });

  wss.on("connection", (ws) => {
    send(ws, { type: "ready" });
    ws.on("message", (raw) => onMessage(service, ws, raw));
    ws.on("close", () => service.disposeForSocket(ws));
    ws.on("error", () => service.disposeForSocket(ws));
  });

  httpServer.listen(port, "127.0.0.1", () => {
    console.log(`>> capture agent service on ws://127.0.0.1:${port} (${IS_MOCK ? "MOCK mode" : "real mode"})`);
    console.log(`>> evidence dir: ${service.dataDir}`);
    if (!IS_MOCK && !process.env.OPENROUTER_API_KEY) {
      console.log(">> WARNING: OPENROUTER_API_KEY not set — asks will report 'agent unavailable'.");
    }
  });

  return { httpServer, wss, service };
}

// Allow a direct `node server.js` start (and keep the module importable for tests).
if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  startServer();
}

"""Capture Server — dumb receiver for the X capture instrument.

Accepts a single POST /api/capture, validates a recursive node tree (a tweet
together with curated comments, each of which is itself a node with the same
shape), stamps `captured_at` on the root on receipt, and appends one JSON
line to `artefacts.jsonl`. It does nothing else — no enrichment, no dedup, no
analysis.

Optionally the root may carry an `agent` envelope (produced by the capture
agent service) pointing at the saved conversation evidence; if present it must
carry `sessionId` + `sessionFile`. The server does not verify the session file
exists at save time — session persistence is the agent service's contract.

It also exposes GET /search — a thin read API over the derived SQLite FTS5
index (see index.py / bin/rebuild-index.py).

Fixed defaults:
  - data file: data/artefacts.jsonl beside this file
  - port: 8765
Each may be overridden by a single env var (CAPTURE_DATA, CAPTURE_PORT,
CAPTURE_INDEX). No config file, no CLI flags.
"""

import json
import os
from datetime import datetime, timezone
from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

from index import CaptureIndex

DEFAULT_PORT = 8765
DEFAULT_DATA_PATH = Path(__file__).resolve().parent / "data" / "artefacts.jsonl"
DEFAULT_INDEX_PATH = Path(__file__).resolve().parent / "data" / "index.db"

# tweet_url is the anchor and the only required field on every node; the rest
# (including children) is optional and may be empty.
REQUIRED_FIELDS = ("tweet_url",)

app = FastAPI(title="Capture Server")


def data_path() -> Path:
    return Path(os.environ.get("CAPTURE_DATA", DEFAULT_DATA_PATH))


def index_path() -> Path:
    return Path(os.environ.get("CAPTURE_INDEX", DEFAULT_INDEX_PATH))


def _index() -> CaptureIndex:
    return CaptureIndex(index_path())


def append_artefact(artefact: dict, path: Path | None = None) -> None:
    """Append one artefact as a JSON line, write + flush. Returns None."""
    target = path if path is not None else data_path()
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open("a", encoding="utf-8") as f:
        f.write(json.dumps(artefact, ensure_ascii=False) + "\n")
        f.flush()


def validate_node(node, path="root") -> None:
    """Validate a node recursively. Raises ValueError with a descriptive
    message on the first problem found. Every nested child must have a
    tweet_url."""
    if not isinstance(node, dict):
        raise ValueError(f"{path} must be an object")
    if not node.get("tweet_url"):
        raise ValueError(f"{path} is missing required field 'tweet_url'")
    children = node.get("children") or []
    if not isinstance(children, list):
        raise ValueError(f"{path}.children must be a list")
    for i, child in enumerate(children):
        validate_node(child, f"{path}.children[{i}]")


@app.post("/api/capture")
async def capture(request: Request):
    try:
        body = await request.json()
    except Exception:
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "invalid JSON body"}
        )

    if not isinstance(body, dict):
        return JSONResponse(
            status_code=400, content={"status": "error", "error": "payload must be an object"}
        )

    try:
        validate_node(body)
    except ValueError as exc:
        return JSONResponse(
            status_code=400,
            content={"status": "error", "error": str(exc)},
        )

    agent = body.get("agent")
    if agent is not None:
        if not isinstance(agent, dict):
            return JSONResponse(
                status_code=400,
                content={"status": "error", "error": "agent must be an object when present"},
            )
        if not agent.get("sessionId") or not agent.get("sessionFile"):
            return JSONResponse(
                status_code=400,
                content={"status": "error", "error": "agent envelope must carry sessionId and sessionFile"},
            )

    captured_at = datetime.now(timezone.utc).isoformat()
    artefact = {
        "tweet_url": body["tweet_url"],
        "author": body.get("author", ""),
        "tweet_text": body.get("tweet_text", ""),
        "links": body.get("links", []),
        "parent_url": body.get("parent_url"),
        "notes": body.get("notes", ""),
        "children": body.get("children", []),
        "captured_at": captured_at,
    }
    if agent is not None:
        artefact["agent"] = agent

    append_artefact(artefact)
    return {"status": "saved", "captured_at": captured_at}


@app.get("/search")
async def search(q: str = "", author: str | None = None, since: str | None = None, limit: int = 50):
    """Read API over the derived FTS5 index (BM25 relevance-ranked).

    GET /search?q=arxiv&author=@user&since=2026-08-01T00:00:00+00:00&limit=50

    The index is derived from artefacts.jsonl; if it does not exist yet it is
    rebuilt on the fly so a fresh checkout still answers.
    """
    idx = _index()
    if not idx.exists():
        # derived + rebuildable: safest to build on first read so /search works
        # right after a fresh start without a manual rebuild step.
        try:
            idx.rebuild(data_path())
        except Exception:
            return JSONResponse(status_code=500, content={"status": "error", "error": "could not build index"})

    try:
        items, total = idx.search(q=q or None, author=author or None, since=since or None, limit=limit)
    except ValueError as exc:
        return JSONResponse(status_code=400, content={"status": "error", "error": str(exc)})
    except Exception as exc:  # pragma: no cover - defensive
        return JSONResponse(status_code=500, content={"status": "error", "error": str(exc)})
    return {"items": items, "total": total, "rank": True}



def main() -> None:
    import uvicorn

    port = int(os.environ.get("CAPTURE_PORT", DEFAULT_PORT))
    uvicorn.run(app, host="127.0.0.1", port=port)


if __name__ == "__main__":
    main()

// Real (pi SDK) agent runner for the capture agent service.
//
// Creates an in-memory AgentSession with exactly one custom tool (fetch_url),
// no coding tools (Decision 03), reasons over the pending capture, streams
// text deltas / tool activity, and on settle hands the full message list back
// so the service can persist it as evidence.

import {
  createAgentSession,
  createExtensionRuntime,
  SessionManager,
  SettingsManager,
} from "@earendil-works/pi-coding-agent";
import { createModelStack, resolveModel } from "./models.mjs";
import { fetchUrlTool } from "./tools/fetch_url.js";
import { serializeTree } from "./serialize.js";

export function makeSystemPrompt() {
  return `You are a research assistant embedded in the Capture instrument. You help the user think about a captured X/Twitter post and the content it links to.

Rules:
- Reason only over the pending capture and the urls inside it.
- When a url in the capture is relevant to the user's question, fetch and read it with the fetch_url tool. You decide which urls matter.
- Use the tool as part of your reasoning, then answer the user's question plainly.
- Be concise and specific. Cite what you actually read; if content is unavailable, say so.
- Never invent, edit, or fabricate content.`;
}

// A fully controlled resource loader: no project/global extensions, skills,
// prompt templates, themes, or context files leak in. Only fetch_url is
// available to the model.
function minimalResourceLoader() {
  return {
    getExtensions: () => ({ extensions: [], errors: [], runtime: createExtensionRuntime() }),
    getSkills: () => ({ skills: [], diagnostics: [] }),
    getPrompts: () => ({ prompts: [], diagnostics: [] }),
    getThemes: () => ({ themes: [], diagnostics: [] }),
    getAgentsFiles: () => ({ agentsFiles: [] }),
    getSystemPrompt: () => makeSystemPrompt(),
    getAppendSystemPrompt: () => [],
    extendResources: () => {},
    reload: async () => {},
  };
}

export class CaptureAgent {
  constructor({ cwd }) {
    this.cwd = cwd || process.cwd();
    this.session = null;
    this.model = null;
    this.handlers = {};
    this.unsub = null;
  }

  get isStreaming() {
    return !!(this.session && this.session.isStreaming);
  }

  async start() {
    const { authStorage, modelRegistry } = createModelStack();
    const model = resolveModel(modelRegistry); // throws if the model is unavailable
    const settingsManager = SettingsManager.inMemory({ compaction: { enabled: false } });
    const { session } = await createAgentSession({
      cwd: this.cwd,
      model,
      thinkingLevel: "medium",
      authStorage,
      modelRegistry,
      settingsManager,
      resourceLoader: minimalResourceLoader(),
      tools: ["fetch_url"],
      customTools: [fetchUrlTool],
      sessionManager: SessionManager.inMemory(this.cwd),
    });
    this.session = session;
    this.model = model;
    this.handlers = {};
    this.unsub = session.subscribe((event) => this._onEvent(event));
    return { model };
  }

  setHandlers(handlers) {
    this.handlers = handlers || {};
  }

  _onEvent(event) {
    if (event.type === "message_update" && event.assistantMessageEvent.type === "text_delta") {
      if (this.handlers.onDelta) this.handlers.onDelta(event.assistantMessageEvent.delta);
    } else if (event.type === "tool_execution_start") {
      if (this.handlers.onTool) {
        this.handlers.onTool({ tool: event.toolName, arg: event.args && event.args.url });
      }
    } else if (event.type === "agent_end") {
      if (this.handlers.onSettled) this.handlers.onSettled(event.messages || []);
    } else if (event.type === "message_end" && this.handlers.onMessageEnd) {
      // reserved
    }
  }

  // First turn: inject the serialized tree (context) then the user's question.
  async ask(tree, prompt) {
    const context = serializeTree(tree || {});
    const userText = prompt && prompt.trim() ? prompt.trim() : "Analyse this capture.";
    await this.session.prompt(`${context}\n\nQuestion: ${userText}`);
  }

  // Follow-up in the same conversation; the session retains capture context.
  async followUp(prompt) {
    await this.session.followUp(prompt && prompt.trim() ? prompt.trim() : "Continue.");
  }

  async abort() {
    if (this.session) await this.session.abort();
  }

  dispose() {
    if (this.unsub) this.unsub();
    if (this.session) this.session.dispose();
    this.session = null;
    this.unsub = null;
  }
}

// Persistence of agent conversations as pi-native session evidence (Decision 04).
//
// One artefact = one capture tree line with an `agent` envelope, and the full
// conversation written verbatim to `data/sessions/<uuid>/session.jsonl` in pi's
// native v3 session format — the same format the factory knowledge base stores
// and `extract-context` understands. Answers are saved verbatim, never edited.

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

export function newSessionId() {
  return crypto.randomUUID();
}

export function newEntryId() {
  return crypto.randomBytes(4).toString("hex");
}

// Sum the reported cost across assistant messages (usage.cost.total). Returns 0
// when usage data is absent (e.g. a stubbed run).
export function costOfMessages(messages) {
  let total = 0;
  for (const msg of messages || []) {
    const cost = msg && msg.usage && msg.usage.cost;
    if (cost && typeof cost.total === "number") total += cost.total;
  }
  return total;
}

export function currentModelOf(messages, fallback) {
  for (const msg of messages || []) {
    if (msg && msg.role === "assistant" && msg.model) return msg.model;
  }
  return fallback || "";
}

// Serialize a list of AgentMessages into a pi-native v3 session.jsonl string.
// First line is the session header; each subsequent line is a `message` entry
// linked by id/parentId into a linear tree (the path pi walks to rebuild the
// context window).
export function serializeSession(messages, { sessionId, cwd }) {
  const header = {
    type: "session",
    version: 3,
    id: sessionId,
    timestamp: new Date().toISOString(),
    cwd: cwd || process.cwd(),
  };
  const lines = [JSON.stringify(header)];
  let parentId = null;
  for (const msg of messages || []) {
    const id = newEntryId();
    const timestamp = new Date(
      typeof msg.timestamp === "number" ? msg.timestamp : Date.now()
    ).toISOString();
    const entry = { type: "message", id, parentId, timestamp, message: msg };
    lines.push(JSON.stringify(entry));
    parentId = id;
  }
  return lines.join("\n") + "\n";
}

// Persist messages to data/sessions/<sessionId>/session.jsonl. Returns the
// envelope fragments the capture server accepts.
export function persistSession(dataDir, sessionId, messages) {
  const dir = path.join(dataDir, "sessions", sessionId);
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, "session.jsonl");
  fs.writeFileSync(file, serializeSession(messages, { sessionId }), "utf8");
  return {
    sessionId,
    sessionFile: path.join("sessions", sessionId, "session.jsonl").split(path.sep).join("/"),
  };
}

// Model stack for the capture agent service (Decision 02).
//
// Inference runs through OpenRouter via pi's ModelRuntime. The API key lives
// ONLY in this service's environment (OPENROUTER_API_KEY) — never in the
// browser. Default model deepseek/deepseek-v4-flash (thinking on), overridable
// with AGENT_MODEL.
//
// Auth + registry are in-memory: nothing sensitive is ever written to disk on
// the host, and the repo stays free of stray credential/registry files. The
// openrouter model is resolved from pi's built-in model registry.

import { AuthStorage, ModelRegistry } from "@earendil-works/pi-coding-agent";

export const DEFAULT_MODEL = "deepseek/deepseek-v4-flash";

// Design note on temperature: pi's session API does not expose a per-session
// temperature knob to SDK callers for reasoning models (temperature lives on
// provider StreamOptions that pi controls internally). The PRD's "~0.2" is
// honoured as documented intent; pi manages temperature for reasoning models
// itself. See outbox decisions.

export function createModelStack() {
  const authStorage = AuthStorage.inMemory();
  if (process.env.OPENROUTER_API_KEY) {
    authStorage.setRuntimeApiKey("openrouter", process.env.OPENROUTER_API_KEY);
  }
  const modelRegistry = ModelRegistry.inMemory(authStorage);
  return { authStorage, modelRegistry };
}

export function resolveModel(modelRegistry) {
  const id = process.env.AGENT_MODEL || DEFAULT_MODEL;
  const model = modelRegistry.find("openrouter", id);
  if (!model) {
    throw new Error(`Model not found on provider "openrouter": ${id}`);
  }
  return model;
}

// fetch_url custom tool for the capture agent.
//
// The ONLY tool the agent gets in v1 (Decision 03): fetch-and-read a url,
// server-side so there is no browser CORS. Bounded with hard caps (body size,
// timeout) so one huge page cannot stall a session. The agent decides which of
// the capture's urls to fetch.

import { defineTool } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

export const MAX_BODY_BYTES = 1024 * 1024; // ~1 MB response body cap
export const TIMEOUT_MS = 30_000; // 30 s overall cap

// Strip markup so the model reads prose, not HTML soup. Kept deliberately
// lightweight — not a full HTML parser.
function htmlToText(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

// Fetch a url with caps using the runtime's global fetch (handles redirects).
// Returns { ok, text } — text is always a string the model can read.
export async function fetchWithCaps(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, text: `fetch_url: invalid URL: ${url}` };
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    return { ok: false, text: `fetch_url: unsupported protocol "${parsed.protocol}" (only http/https)` };
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

  let res;
  try {
    res = await fetch(parsed.href, {
      signal: controller.signal,
      redirect: "follow",
      headers: {
        "user-agent": "capture-agent-service/0.1 (local reasoning agent)",
        accept: "text/html,text/plain;q=0.9,*/*;q=0.8",
      },
    });
  } catch (e) {
    clearTimeout(timer);
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "unknown fetch error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }

  if (!res.ok) {
    clearTimeout(timer);
    if (res.body && res.body.cancel) await res.body.cancel().catch(() => {});
    return { ok: false, text: `fetch_url: HTTP ${res.status} for ${url}` };
  }

  const contentType = String(res.headers.get("content-type") || "").toLowerCase();
  const declaredLength = parseInt(String(res.headers.get("content-length") || "0"), 10);
  if (declaredLength > MAX_BODY_BYTES) {
    clearTimeout(timer);
    if (res.body && res.body.cancel) await res.body.cancel().catch(() => {});
    return { ok: false, text: `fetch_url: response too large (${declaredLength} bytes > 1 MB cap)` };
  }

  const reader = res.body.getReader();
  const chunks = [];
  let total = 0;
  let tooLarge = false;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.length;
      if (total > MAX_BODY_BYTES) {
        tooLarge = true;
        break;
      }
      chunks.push(value);
    }
  } catch (e) {
    clearTimeout(timer);
    if (tooLarge) {
      return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
    }
    const reason = e && e.name === "AbortError" ? `timed out after ${TIMEOUT_MS / 1000}s` : e && e.message ? e.message : "read error";
    return { ok: false, text: `fetch_url: ${reason}` };
  }
  clearTimeout(timer);
  if (tooLarge) {
    await reader.cancel().catch(() => {});
    return { ok: false, text: "fetch_url: response body exceeded 1 MB cap, content truncated" };
  }

  let bodyText;
  try {
    bodyText = Buffer.concat(chunks).toString("utf8");
  } catch {
    bodyText = "";
  }
  const isHtml = contentType.includes("html");
  const text = (isHtml ? htmlToText(bodyText) : bodyText).trim();
  if (!text) {
    return { ok: false, text: `fetch_url: no readable text content at ${url}` };
  }
  return { ok: true, text };
}

export const fetchUrlTool = defineTool({
  name: "fetch_url",
  label: "Fetch URL",
  description:
    "Fetch and read the text content of a URL (HTML or plain text). Runs server-side, body capped at ~1 MB and 30s timeout. Use only for urls present in the capture being analyzed.",
  parameters: Type.Object({
    url: Type.String({ description: "The http(s) URL to fetch and read." }),
  }),
  execute: async (_toolCallId, params) => {
    const { ok, text } = await fetchWithCaps(params.url);
    return {
      content: [{ type: "text", text }],
      details: { ok, url: params.url },
    };
  },
});

// Serialize a capture tree into a compact text block that is injected inline
// into the agent's first prompt. This is the "context injection" seam: the
// root tweet plus curated comment nodes (text + urls) become the raw material
// the agent reasons over.

function nodeToText(node, depth, lines) {
  const pad = "  ".repeat(depth);
  const author = node.author ? `${node.author}` : "unknown author";
  const text = node.tweet_text && node.tweet_text.trim() ? node.tweet_text.trim() : "(no text)";
  lines.push(`${pad}- ${author}: ${text}`);
  if (Array.isArray(node.links) && node.links.length) {
    for (const link of node.links) {
      lines.push(`${pad}  url: ${link}`);
    }
  }
  if (node.tweet_url) {
    lines.push(`${pad}  source: ${node.tweet_url}`);
  }
  if (node.notes && node.notes.trim()) {
    lines.push(`${pad}  notes: ${node.notes.trim()}`);
  }
  for (const child of node.children || []) {
    nodeToText(child, depth + 1, lines);
  }
}

export function serializeTree(tree) {
  const lines = [];
  lines.push("Here is the pending capture you are being asked about:");
  nodeToText(tree || {}, 0, lines);
  return lines.join("\n");
}

// Side panel logic for Capture.
// Renders the in-progress capture as a live view: the root tweet plus any
// curated comments nested in an indented tree. Re-renders live when the
// content script adds/removes comments (via background broadcast). On Save it
// POSTs the whole recursive tree to the local server.

(() => {
  "use strict";

  const statusEl = document.getElementById("status");
  const contentEl = document.getElementById("content");
  const authorEl = document.getElementById("author");
  const urlEl = document.getElementById("tweet-url");
  const scrapeWarnEl = document.getElementById("scrape-warning");
  const textEl = document.getElementById("tweet-text");
  const linksEl = document.getElementById("links");
  const notesEl = document.getElementById("notes");
  const contextFieldset = document.getElementById("context-fieldset");
  const contextLegend = document.getElementById("context-legend");
  const contextTree = document.getElementById("context-tree");
  const saveBtn = document.getElementById("save");

  // Ask panel (agent)
  const agentFieldset = document.getElementById("agent-fieldset");
  const agentThread = document.getElementById("agent-thread");
  const agentStatus = document.getElementById("agent-status");
  const agentInput = document.getElementById("agent-input");
  const agentAskBtn = document.getElementById("agent-ask");
  const agentAbortBtn = document.getElementById("agent-abort");
  const agentUnavailable = document.getElementById("agent-unavailable");

  let agentUrl = "ws://127.0.0.1:8766";
  let agentBusy = false;
  let agentEnvelope = null; // stashed when the agent settles (attached on Save)
  let agentEverAvail = false;
  let agentPending = null; // { tree, prompt } waiting for a connection
  let agentMessages = []; // { role, content } transcript for reconnection context
  let agentClient = null;

  let serverUrl = "http://127.0.0.1:8765/api/capture";
  let current = null; // the root node of the in-progress capture (has children[])

  function setStatus(msg, kind) {
    statusEl.textContent = "";
    statusEl.className = "status " + (kind || "pending");
    statusEl.innerHTML = msg;
  }

  function clearStatus() {
    statusEl.textContent = "";
    statusEl.className = "";
  }

  function renderLinks(list) {
    linksEl.innerHTML = "";
    const arr = Array.isArray(list) ? list : [];
    if (arr.length === 0) {
      const li = document.createElement("li");
      li.className = "empty";
      li.textContent = "No links found.";
      linksEl.appendChild(li);
      return;
    }
    for (const link of arr) {
      const li = document.createElement("li");
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = link;
      cb.checked = true;
      const label = document.createElement("label");
      label.textContent = link;
      li.appendChild(cb);
      li.appendChild(label);
      linksEl.appendChild(li);
    }
  }

  // Build one comment node row, indented by depth. Comment links are shown
  // plainly (captured automatically; no per-node toggles in v1).
  function nodeEl(node, depth) {
    const div = document.createElement("div");
    div.className = "cnode";
    div.style.paddingLeft = 6 + depth * 16 + "px";

    if (node.author) {
      const a = document.createElement("div");
      a.className = "c-author";
      a.textContent = node.author;
      div.appendChild(a);
    }
    const t = document.createElement("div");
    t.className = "c-text";
    t.textContent = node.tweet_text || "(no text scraped)";
    div.appendChild(t);
    if (node.tweet_url) {
      const u = document.createElement("span");
      u.className = "c-url";
      u.textContent = node.tweet_url;
      div.appendChild(u);
    }
    if (Array.isArray(node.links) && node.links.length) {
      const ul = document.createElement("ul");
      for (const link of node.links) {
        const li = document.createElement("li");
        li.textContent = link;
        ul.appendChild(li);
      }
      div.appendChild(ul);
    }
    return div;
  }

  function renderChildren(parentNode, depth, container) {
    for (const child of parentNode.children || []) {
      container.appendChild(nodeEl(child, depth));
      renderChildren(child, depth + 1, container);
    }
  }

  // Re-render the Context (comments tree) section only — called on live
  // updates so notes/text edits in the panel aren't clobbered.
  function renderContext() {
    const kids = (current && current.children) || [];
    contextFieldset.style.display = kids.length ? "block" : "none";
    contextLegend.textContent = "Context (" + kids.length + ")";
    contextTree.innerHTML = "";
    if (kids.length) renderChildren(current, 1, contextTree);
  }

  function renderRoot() {
    const node = current || {};
    authorEl.textContent = node.author || "Unknown author";
    urlEl.textContent = node.tweet_url || "";
    textEl.value = node.tweet_text || "";
    if (!node.tweet_text && !node.tweet_url) {
      scrapeWarnEl.style.display = "block";
    } else {
      scrapeWarnEl.style.display = "none";
    }
    renderLinks(node.links || []);
  }

  function render(data) {
    current = data || { tweet_url: "", author: "", tweet_text: "", links: [], parent_url: null, notes: "", children: [] };
    renderRoot();
    renderContext();
    notesEl.value = current.notes || "";
    contentEl.style.display = "block";
    clearStatus();
    resetAgentForNewCapture();
  }

  // Deep-clone current into a tree, apply panel edits (root text, notes,
  // checked root links), and return it for submission.
  function collectArtefact() {
    const tree = JSON.parse(JSON.stringify(current || {}));
    tree.tweet_text = textEl.value.trim();
    tree.notes = notesEl.value.trim();
    const checkedLinks = [];
    for (const li of linksEl.querySelectorAll("li")) {
      const cb = li.querySelector('input[type="checkbox"]');
      if (cb && cb.checked && cb.value) checkedLinks.push(cb.value);
    }
    tree.links = checkedLinks;
    return tree;
  }

  async function submit() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to save — no tweet URL.", "error");
      return;
    }
    const artefact = collectArtefact();
    if (agentEnvelope) artefact.agent = agentEnvelope; // link the saved evidence
    saveBtn.disabled = true;
    setStatus("Saving…", "pending");
    try {
      const resp = await fetch(serverUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(artefact),
      });
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const body = await resp.json();
      setStatus(
        "Saved ✓ " + (body.captured_at ? "at " + body.captured_at : ""),
        "ok"
      );
      chrome.runtime.sendMessage({ type: "clear-pending-capture" });
      saveBtn.disabled = false;
    } catch (e) {
      setStatus(
        "<strong>Server offline</strong> — restart and try again. Your data is still here.",
        "error"
      );
      saveBtn.disabled = false;
    }
  }

  saveBtn.addEventListener("click", submit);

  // ------------------------------------------------------------------------
  // Agent (Ask) — stories 1-5
  // ------------------------------------------------------------------------

  function setAgentStatus(msg, kind) {
    if (!msg) {
      agentStatus.style.display = "none";
      agentStatus.className = "status";
      agentStatus.textContent = "";
      return;
    }
    agentStatus.style.display = "block";
    agentStatus.className = "status " + (kind || "pending");
    agentStatus.textContent = msg;
  }

  function showAgentUnavailable() {
    agentUnavailable.style.display = "block";
    agentFieldset.style.opacity = "0.75";
  }

  function hideAgentUnavailable() {
    agentUnavailable.style.display = "none";
    agentFieldset.style.opacity = "";
  }

  function addAgentBubble(cls, text) {
    const div = document.createElement("div");
    div.className = "agent-msg " + cls;
    div.textContent = text || "";
    agentThread.appendChild(div);
    return div;
  }

  function updateAgentControls() {
    agentAskBtn.disabled = agentBusy || !!(current && current.tweet_url) === false;
    agentAbortBtn.style.display = agentBusy ? "inline-block" : "none";
    agentAskBtn.style.display = agentBusy ? "none" : "inline-block";
  }

  function captureId() {
    return current && current.tweet_url ? "capture:" + current.tweet_url : "capture:active";
  }

  function appendDeliveredText(text) {
    if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
    currentAssistantBubble.textContent += text;
    currentAssistantText += text;
    agentThread.scrollTop = agentThread.scrollHeight;
  }

  function flushPendingIfConnected() {
    if (agentPending && agentClient && agentClientWasOpen()) {
      agentClient.ask(agentPending.captureId, agentPending.tree, agentPending.prompt, agentPending.messages);
      agentPending = null;
    }
  }

  function agentClientWasOpen() {
    return agentClient && agentClient.ws && agentClient.ws.readyState === WebSocket.OPEN;
  }

  function initAgentClient() {
    if (agentClient) return;
    agentClient = new AgentClient({
      url: agentUrl,
      handlers: {
        onReady: () => {
          agentEverAvail = true;
          hideAgentUnavailable();
          setAgentStatus("Connected.", "ok");
          setTimeout(() => setAgentStatus(null), 1200);
          flushPendingIfConnected();
        },
        onDelta: (msg) => {
          if (msg.captureId !== captureId()) return;
          appendDeliveredText(msg.text);
        },
        onTool: (msg) => {
          if (msg.captureId !== captureId()) return;
          addAgentBubble("tool", "⚙ fetched " + (msg.arg || msg.tool));
        },
        onSettled: (msg) => {
          if (msg.captureId !== captureId()) return;
          // finalize assistant bubble, stash the envelope for Save
          if (!currentAssistantBubble) currentAssistantBubble = addAgentBubble("assistant", "");
          if (msg.model) {
            const meta = document.createElement("div");
            meta.className = "muted";
            meta.style.cssText = "margin-top:4px;font-size:11px;";
            meta.textContent = "model " + msg.model + (typeof msg.cost === "number" ? " · $" + msg.cost.toFixed(5) : "");
            currentAssistantBubble.appendChild(meta);
          }
          currentAssistantBubble = null;
          agentEnvelope = {
            sessionId: msg.sessionId,
            sessionFile: msg.sessionFile,
            prompt: lastAgentPrompt || "",
            model: msg.model || "",
            capturedAt: new Date().toISOString(),
            cost: typeof msg.cost === "number" ? msg.cost : undefined,
          };
          agentMessages.push({ role: "assistant", content: currentAssistantText });
          currentAssistantText = "";
          agentBusy = false;
          updateAgentControls();
          setAgentStatus("Answer saved with this capture.", "ok");
          setTimeout(() => setAgentStatus(null), 1500);
        },
        onError: (msg) => {
          agentBusy = false;
          updateAgentControls();
          if (msg && /unreachable|unavailable/i.test(msg.message || "")) {
            showAgentUnavailable();
            setAgentStatus("Agent unavailable. You can still save.", "error");
          } else {
            setAgentStatus("Agent error: " + ((msg && msg.message) || "unknown"), "error");
          }
        },
        onDown: (msg) => {
          // service is not up yet — show the unavailable state, keep retrying
          showAgentUnavailable();
          setAgentStatus("Agent unavailable. You can still save.", "error");
        },
      },
    });
    agentClient.connect();
  }

  let currentAssistantBubble = null;
  let currentAssistantText = "";
  let lastAgentPrompt = "";

  function askAgent() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to ask about — no tweet URL.", "error");
      return;
    }
    const prompt = agentInput.value.trim();
    if (!prompt) return;
    if (agentBusy) return;

    const tree = collectArtefact();
    lastAgentPrompt = prompt;
    addAgentBubble("user", prompt);
    agentMessages.push({ role: "user", content: prompt });
    agentInput.value = "";
    currentAssistantBubble = null;
    currentAssistantText = "";
    agentBusy = true;
    updateAgentControls();
    hideAgentUnavailable();

    if (agentClientWasOpen()) {
      agentClient.ask(captureId(), tree, prompt, []);
    } else {
      agentPending = { captureId: captureId(), tree, prompt, messages: agentMessages.slice() };
      setAgentStatus("Connecting to agent service…", "pending");
      initAgentClient();
    }
  }

  function followUpAgent() {
    if (agentBusy) return;
    const prompt = agentInput.value.trim();
    if (!prompt) return;
    if (!agentEverAvail) {
      askAgent();
      return;
    }
    lastAgentPrompt = prompt;
    addAgentBubble("user", prompt);
    agentMessages.push({ role: "user", content: prompt });
    agentInput.value = "";
    currentAssistantBubble = null;
    currentAssistantText = "";
    agentBusy = true;
    updateAgentControls();
    if (agentClientWasOpen()) {
      agentClient.followUp(captureId(), prompt);
    } else {
      agentPending = { captureId: captureId(), tree: collectArtefact(), prompt, messages: agentMessages.slice() };
      setAgentStatus("Reconnecting to agent service…", "pending");
      initAgentClient();
    }
  }

  agentInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (agentEverAvail) followUpAgent();
      else askAgent();
    }
  });
  agentAskBtn.addEventListener("click", askAgent);
  agentAbortBtn.addEventListener("click", () => {
    if (agentClient) agentClient.abort(captureId());
    agentBusy = false;
    currentAssistantBubble = null;
    currentAssistantText = "";
    updateAgentControls();
    setAgentStatus("Stopped.", "pending");
  });

  function resetAgentForNewCapture() {
    agentEnvelope = null;
    agentMessages = [];
    lastAgentPrompt = "";
    currentAssistantBubble = null;
    agentBusy = false;
    agentThread.innerHTML = "";
    updateAgentControls();
    if (agentEverAvail) hideAgentUnavailable();
    else if (agentClient) showAgentUnavailable();
  }

  // Live updates from the background (content added/removed a comment).
  chrome.runtime.onMessage.addListener((message) => {
    if (!message) return;
    if (message.type === "capture-updated") {
      chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
        if (chrome.runtime.lastError || !resp || !resp.data) return;
        current = resp.data;
        renderContext(); // refresh tree only; keep notes/text edits
      });
    } else if (message.type === "capture-cleared") {
      // Capture completed — reset the panel to the empty prompt.
      current = null;
      currentAssistantBubble = null;
      contentEl.style.display = "none";
      resetAgentForNewCapture();
      setStatus("Capture complete. Hover a tweet on X and click <strong>Capture</strong> to start again.", "ok");
    }
  });

  // Ask background for the pending capture (survives page navigation).
  chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
    if (chrome.runtime.lastError) {
      setStatus("Background unavailable. Reopen the panel.", "error");
      return;
    }
    if (resp && resp.serverUrl) serverUrl = resp.serverUrl;
    if (resp && resp.data) {
      render(resp.data);
    } else {
      contentEl.style.display = "none";
      setStatus("No pending capture. Hover a tweet on X and click <strong>Capture</strong>.", "pending");
    }
  });
})();

// Thin WebSocket client for the capture agent service (ws://127.0.0.1:8766).
//
// Connects with reconnect/backoff, sends { ask | follow_up | abort }, and
// emits the incoming protocol events (delta/tool/settled/error/ready) to
// registered handlers. Kept deliberately small and dependency-free (no
// framework) because it runs inside the MV3 side panel.

class AgentClient {
  /**
   * @param {object} opts
   * @param {string} [opts.url]   ws url (default ws://127.0.0.1:8766)
   * @param {object} [opts.handlers] { onOpen, onDelta, onTool, onSettled, onError, onReady }
   */
  constructor(opts = {}) {
    this.url = opts.url || "ws://127.0.0.1:8766";
    this.handlers = opts.handlers || {};
    this.ws = null;
    this.attempt = 0;
    this.everConnected = false;
    this.maxAttempts = opts.maxAttempts || 8;
    this.baseDelay = opts.baseDelay || 500; // ms
    this.reconnectTimer = null;
    this.manualClose = false;
  }

  connect() {
    this.manualClose = false;
    this._open();
  }

  _open() {
    let ws;
    try {
      ws = new WebSocket(this.url);
    } catch (e) {
      this._scheduleReconnect();
      return;
    }
    this.ws = ws;

    ws.onopen = () => {
      this.attempt = 0;
      this.everConnected = true;
      if (this.handlers.onOpen) this.handlers.onOpen();
    };

    ws.onmessage = (event) => {
      let msg;
      try {
        msg = JSON.parse(event.data);
      } catch (e) {
        return;
      }
      this._dispatch(msg);
    };

    ws.onerror = () => {
      // onerror is followed by onclose; let onclose handle reconnect.
    };

    ws.onclose = () => {
      this.ws = null;
      if (this.manualClose) return;
      if (!this.everConnected && this.handlers.onDown) {
        // never managed to connect — surface "service down" right away
        this.handlers.onDown({ type: "error", message: "agent service unreachable" });
      }
      this._scheduleReconnect();
    };
  }

  _scheduleReconnect() {
    if (this.attempt >= this.maxAttempts) {
      if (this.handlers.onError) {
        this.handlers.onError({ type: "error", message: "agent service unreachable" });
      }
      return;
    }
    const delay = this.baseDelay * Math.pow(2, this.attempt);
    this.attempt += 1;
    this.reconnectTimer = setTimeout(() => this._open(), delay);
  }

  _dispatch(msg) {
    switch (msg.type) {
      case "ready":
        if (this.handlers.onReady) this.handlers.onReady();
        break;
      case "delta":
        if (this.handlers.onDelta) this.handlers.onDelta(msg);
        break;
      case "tool":
        if (this.handlers.onTool) this.handlers.onTool(msg);
        break;
      case "settled":
        if (this.handlers.onSettled) this.handlers.onSettled(msg);
        break;
      case "error":
        if (this.handlers.onError) this.handlers.onError(msg);
        break;
      default:
        break;
    }
  }

  send(obj) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(obj));
      return true;
    }
    return false;
  }

  ask(captureId, tree, prompt, messages) {
    return this.send({ type: "ask", captureId, tree, messages: messages || [], prompt });
  }

  followUp(captureId, prompt) {
    return this.send({ type: "follow_up", captureId, prompt });
  }

  abort(captureId) {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: "abort", captureId }));
    }
  }

  close() {
    this.manualClose = true;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.ws) this.ws.close();
    this.ws = null;
  }
}

