+// Smoke test for the capture agent service protocol.
+//
+// Connects to a running service (default ws://127.0.0.1:8766), sends an `ask`,
+// then a `follow_up`, and asserts the protocol contract: deltas arrive, a
+// `settled` event returns a sessionId + sessionFile, and the session evidence
+// file exists on disk. Designed to run against AGENT_MOCK=1 (no OpenRouter key
+// needed) — see package.json "smoke" script.
+//
+// Usage:  node test/smoke.mjs [ws-url]
+
+import WebSocket from "ws";
+import fs from "node:fs";
+import path from "node:path";
+
+const url = process.argv[2] || "ws://127.0.0.1:8766";
+const dataDir = process.env.AGENT_DATA_DIR || path.resolve(process.cwd(), "..", "server", "data");
+
+const captureId = "smoke-c1";
+const tree = {
+  tweet_url: "https://x.com/user/status/123",
+  author: "@user",
+  tweet_text: "A tweet about arxiv and open source.",
+  links: ["https://arxiv.org/abs/1234"],
+  parent_url: null,
+  notes: "",
+  children: [],
+};
+
+const ws = new WebSocket(url);
+const events = [];
+let settled = null;
+let deltas = 0;
+let settledCount = 0;
+
+function fail(msg) {
+  console.error("SMOKE FAIL:", msg);
+  process.exit(1);
+}
+
+const timeout = setTimeout(() => fail(`timed out waiting for settled (events: ${events.join(",")})`), 20000);
+
+ws.on("open", () => {
+  ws.send(JSON.stringify({ type: "ask", captureId, tree, prompt: "Summarise this post and its core claim." }));
+});
+
+ws.on("message", (raw) => {
+  const msg = JSON.parse(raw.toString());
+  events.push(msg.type);
+  if (msg.type === "delta" && msg.captureId === captureId) deltas += 1;
+  if (msg.type === "error") fail(`service error: ${msg.message}`);
+  if (msg.type === "settled" && msg.captureId === captureId) {
+    settled = msg;
+    settledCount += 1;
+    // verify evidence file exists
+    const file = path.resolve(dataDir, msg.sessionFile);
+    console.log(`>> settled: sessionId=${msg.sessionId} sessionFile=${msg.sessionFile} model=${msg.model} cost=${msg.cost}`);
+    if (!fs.existsSync(file)) fail(`session evidence file not found: ${file}`);
+    const content = fs.readFileSync(file, "utf8");
+    const lines = content.trim().split("\n");
+    if (!lines[0] || !lines[0].includes('"type":"session"')) fail("session file missing header");
+    if (deltas === 0) fail("expected at least one delta before settled");
+    // follow up on same conversation
+    ws.send(JSON.stringify({ type: "follow_up", captureId, prompt: "What would you fetch to verify the claim?" }));
+  }
+  if (settled && msg.type === "settled" && msg.captureId === captureId && settledCount === 2) {
+    // second settled (follow-up turn) confirms context reuse across turns
+    clearTimeout(timeout);
+    console.log("SMOKE PASS: ask -> deltas -> settled -> follow_up -> settled; evidence persisted.");
+    process.exit(0);
+  }
+});
+
+ws.on("error", (e) => fail(`websocket error: ${e && e.message}`));
