+#!/usr/bin/env python3
+"""Rebuild the capture search index (data/index.db) from data/artefacts.jsonl.
+
+The index is DERIVED — safe to delete and rebuild any time. Plain files
+(artefacts.jsonl + sessions/) remain the canonical source of truth.
+
+Usage (from capture/server/):
+    .venv/bin/python bin/rebuild-index.py
+
+Options:
+    --artefacts PATH   alternative artefacts.jsonl (default: data/artefacts.jsonl)
+    --index PATH       alternative index.db (default: data/index.db)
+    --verbose          print the artefact count
+"""
+
+import sys
+from pathlib import Path
+
+# Make server/ importable when run as a script from anywhere.
+SERVER_DIR = Path(__file__).resolve().parent.parent
+sys.path.insert(0, str(SERVER_DIR))
+
+from index import CaptureIndex, DEFAULT_INDEX_PATH  # noqa: E402
+
+
+def main() -> None:
+    import argparse
+
+    parser = argparse.ArgumentParser(description="Rebuild the capture search index from artefacts.jsonl")
+    parser.add_argument("--artefacts", default=None, help="path to artefacts.jsonl")
+    parser.add_argument("--index", default=None, help="output index.db path")
+    parser.add_argument("--verbose", action="store_true", help="print the artefact count")
+    args = parser.parse_args()
+
+    artefacts = Path(args.artefacts) if args.artefacts else DEFAULT_INDEX_PATH.parent / "artefacts.jsonl"
+    index = CaptureIndex(args.index)
+    index.rebuild(artefacts)
+
+    if args.verbose:
+        with index.connect() as conn:
+            n = conn.execute("SELECT COUNT(*) AS n FROM captures").fetchone()["n"]
+        print(f"Indexed {n} capture(s) from {artefacts} -> {index.path}")
+    else:
+        print(f"Rebuilt index from {artefacts} -> {index.path}")
+
+
+if __name__ == "__main__":
+    main()
